  assert.throws(
    () =>
      normalizeRecoveryTarget({
        provider: "paypal",
        apply: false,
        paypalToken: sensitive.paypalToken,
        paypalOrderId: sensitive.paypalOrder,
        paypalCaptureId: sensitive.paypalCapture,
