  assert.throws(
    () =>
      normalizeRecoveryTarget({
        provider: "stripe",
        apply: false,
        stripeSessionId: sensitive.stripeSession,
        paypalToken: sensitive.paypalToken,
      }),
    /cannot include PayPal/,
  )
})

